insert into public.question_options (id, question_id, position, text) values ('1a7cebbe-c470-40e1-8165-cafe8bad7ec7'::uuid, '8fef2d56-28a1-4bf5-8825-7daa5e735019'::uuid, 3, '{"en":"Jupiter"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('a544c486-218e-458b-81fa-da3856e4d353'::uuid, '8fef2d56-28a1-4bf5-8825-7daa5e735019'::uuid, 4, '{"en":"Mercury"}'::jsonb);
insert into public.question_answer_keys (question_id, correct_option_id, rationale) values ('8fef2d56-28a1-4bf5-8825-7daa5e735019'::uuid, '80e436cd-2b83-4c5d-86ab-c7a9cdfb9405'::uuid, '{"en":"Sample item about astronomy. It contains no clinical content."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('80e436cd-2b83-4c5d-86ab-c7a9cdfb9405'::uuid, '8fef2d56-28a1-4bf5-8825-7daa5e735019'::uuid, '{"en":"Iron oxide on its surface gives Mars its reddish colour."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('5f6488fd-aa8e-40f7-8bc6-b8a2dbff2f8c'::uuid, '8fef2d56-28a1-4bf5-8825-7daa5e735019'::uuid, '{"en":"Venus is covered in thick pale clouds and is not red."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('1a7cebbe-c470-40e1-8165-cafe8bad7ec7'::uuid, '8fef2d56-28a1-4bf5-8825-7daa5e735019'::uuid, '{"en":"Jupiter is a banded gas giant with white, orange and brown cloud layers."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('a544c486-218e-458b-81fa-da3856e4d353'::uuid, '8fef2d56-28a1-4bf5-8825-7daa5e735019'::uuid, '{"en":"Mercury is a small grey, cratered world with no reddish surface."}'::jsonb);
