insert into public.question_options (id, question_id, position, text) values ('6927e951-25e1-4760-8917-210e2740e2ed'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, 1, '{"en":"Sunday, two weeks later"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('63102916-3f58-45f0-8601-fa1717750001'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, 2, '{"en":"Monday, two weeks later"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('13c987f1-f511-40bd-817a-769a4288acbe'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, 3, '{"en":"Friday, the same week"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('bf58a2fe-dbde-4e1c-8d26-a8524490f8ed'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, 4, '{"en":"Tuesday, two weeks later"}'::jsonb);
insert into public.question_answer_keys (question_id, correct_option_id, rationale) values ('f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, '63102916-3f58-45f0-8601-fa1717750001'::uuid, '{"en":"Sample item about counting days. It contains no clinical content."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('6927e951-25e1-4760-8917-210e2740e2ed'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, '{"en":"That would be thirteen days, one day short of the 14-day period."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('63102916-3f58-45f0-8601-fa1717750001'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, '{"en":"Fourteen days is exactly two weeks, so the due weekday matches the borrowing weekday."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('13c987f1-f511-40bd-817a-769a4288acbe'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, '{"en":"A Friday in the same week would be only four days later."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('bf58a2fe-dbde-4e1c-8d26-a8524490f8ed'::uuid, 'f4eb1d47-50e3-4c3c-8daa-4573a50b6830'::uuid, '{"en":"That would be fifteen days, one day over the 14-day period."}'::jsonb);
insert into public.question_items (id, code, kind, status, origin, domain_id, difficulty, stem, source_note, version)
insert into public.question_options (id, question_id, position, text) values ('cfdda6f0-0ad6-468d-8f2b-6210f2b2663b'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, 1, '{"en":"The flour must cool to room temperature"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('90d2237c-c6b4-4207-80cd-00689ffb5ebc'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, 2, '{"en":"The salt needs time to turn into sugar"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('aa1e0cfc-1be0-41d0-80c6-f0fed2f746d2'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, 3, '{"en":"The yeast produces gas that makes the dough rise"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('040ade11-f692-49fa-88fb-5c5d99faa8e8'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, 4, '{"en":"The water must evaporate completely"}'::jsonb);
insert into public.question_answer_keys (question_id, correct_option_id, rationale) values ('ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, 'aa1e0cfc-1be0-41d0-80c6-f0fed2f746d2'::uuid, '{"en":"Sample item about baking. It contains no clinical content."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('cfdda6f0-0ad6-468d-8f2b-6210f2b2663b'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, '{"en":"Flour is not heated, so there is nothing to cool down."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('90d2237c-c6b4-4207-80cd-00689ffb5ebc'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, '{"en":"Salt does not change into sugar at any stage of baking."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('aa1e0cfc-1be0-41d0-80c6-f0fed2f746d2'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, '{"en":"Resting gives yeast time to produce carbon dioxide, which expands the dough."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('040ade11-f692-49fa-88fb-5c5d99faa8e8'::uuid, 'ed8bd5a3-4e22-4d55-8cff-5a8635709b29'::uuid, '{"en":"If the water fully evaporated the dough would become dry and crumbly."}'::jsonb);
