insert into public.question_options (id, question_id, position, text) values ('21cc3c24-d518-4678-89c5-c4ff3cd8cea6'::uuid, '5442d616-1d1b-462c-8381-bd3eb938cb3d'::uuid, 3, '{"en":"09:00"}'::jsonb);
insert into public.question_options (id, question_id, position, text) values ('5043802e-5dd9-44d6-8f16-9d791b2db32f'::uuid, '5442d616-1d1b-462c-8381-bd3eb938cb3d'::uuid, 4, '{"en":"08:40"}'::jsonb);
insert into public.question_answer_keys (question_id, correct_option_id, rationale) values ('5442d616-1d1b-462c-8381-bd3eb938cb3d'::uuid, '5043802e-5dd9-44d6-8f16-9d791b2db32f'::uuid, '{"en":"Sample arithmetic item with a fictional timetable. It contains no clinical content."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('315e581a-43aa-4f64-8be7-158c0681d3d2'::uuid, '5442d616-1d1b-462c-8381-bd3eb938cb3d'::uuid, '{"en":"08:00 is only three intervals after 06:00 and would be the fourth ferry."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('a83fa290-df7d-4117-8ea6-5ca2201433f7'::uuid, '5442d616-1d1b-462c-8381-bd3eb938cb3d'::uuid, '{"en":"08:20 would be the fourth departure counted from a wrong start."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('21cc3c24-d518-4678-89c5-c4ff3cd8cea6'::uuid, '5442d616-1d1b-462c-8381-bd3eb938cb3d'::uuid, '{"en":"09:00 is not on the 40-minute pattern that starts at 06:00."}'::jsonb);
insert into public.question_explanations (option_id, question_id, explanation) values ('5043802e-5dd9-44d6-8f16-9d791b2db32f'::uuid, '5442d616-1d1b-462c-8381-bd3eb938cb3d'::uuid, '{"en":"The fifth ferry is four intervals after 06:00, so 4 x 40 = 160 minutes later, at 08:40."}'::jsonb);
