insert into public.question_explanations (option_id, question_id, explanation) values ('f8ff8040-9682-4041-8bbd-bc97b4007845'::uuid, 'ba20a167-6d6a-4549-8119-feee8a400ff0'::uuid, '{"en":"20 is the perimeter of the garden, not its area."}'::jsonb);
