insert into public.question_options (id, question_id, position, text) values ('dce194aa-391c-49e5-8181-dbf32c8a3733'::uuid, '7fedb6e1-d54d-4051-8b73-cb93363b8d8b'::uuid, 2, '{"en":"Ben wins because he holds more cards"}'::jsonb);
