insert into public.question_explanations (option_id, question_id, explanation) values ('76c19fe0-af94-45ce-8471-0ca26ebb9a98'::uuid, '7fedb6e1-d54d-4051-8b73-cb93363b8d8b'::uuid, '{"en":"The sample rule ends the round as soon as one player holds no cards."}'::jsonb);
